  void FillSketchInspector(){if(editingSketch==null)return;inspector.Controls.Clear();var flow=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(10)};inspector.Controls.Add(flow);flow.Controls.Add(Label("ЭСКИЗ\n"+editingSketch.Name,50));var plane=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};plane.Items.AddRange(new[]{"XY","XZ","YZ"});plane.SelectedItem=canvas.Sketch.Plane;flow.Controls.Add(plane);if(canvas.Sketch.FaceBody!=null)flow.Controls.Add(Label("На грани "+(canvas.Sketch.Face+1)+" выбранного тела. Смена плоскости отключит привязку к грани.",60));plane.SelectedIndexChanged+=(s,e)=>{canvas.Sketch.Plane=plane.Text;canvas.Sketch.FaceBody=null;};var origin=new TextBox{Width=280,Text=string.Join("; ",canvas.Sketch.Origin.Select(Engine.N))};flow.Controls.Add(Label("Начало плоскости X; Y; Z, мм",24));flow.Controls.Add(origin);AddAction(flow,"Применить начало плоскости",()=>{try{canvas.Sketch.Origin=ReadPoint(origin.Text);canvas.Invalidate();}catch(Exception ex){ShowError(ex);}});var snap=new CheckBox{Text="Привязка к сетке",Checked=canvas.Snap,Width=180};snap.CheckedChanged+=(s,e)=>canvas.Snap=snap.Checked;flow.Controls.Add(snap);var step=new NumericUpDown{DecimalPlaces=2,Minimum=.01m,Maximum=100,Value=(decimal)canvas.Step,Width=120};step.ValueChanged+=(s,e)=>{canvas.Step=(double)step.Value;canvas.Invalidate();};flow.Controls.Add(step);
   var selected=canvas.Sketch.Entities.FirstOrDefault(e=>canvas.Selected.Contains(e.Id));if(selected!=null){flow.Controls.Add(Label(CADTools.EntityName(selected.Kind)+" · выбрано "+canvas.Selected.Count,28));var fields=new Dictionary<string,string>();if(new[]{"circle","polygon","slot"}.Contains(selected.Kind))fields["Radius"]=selected.Radius;if(new[]{"rectangle","slot"}.Contains(selected.Kind))fields["Width"]=selected.Width;if(selected.Kind=="rectangle")fields["Height"]=selected.Height;if(selected.Kind=="polygon")fields["Count"]=selected.Count;CADValueEditor editor=null;if(fields.Count>0){editor=new CADValueEditor(fields){Width=280};flow.Controls.Add(editor);}var points=new DataGridView{Width=280,Height=Math.Min(160,50+selected.Points.Count*25),AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};points.Columns.Add("x","X, мм");points.Columns.Add("y","Y, мм");foreach(var p in selected.Points)points.Rows.Add(Engine.N(p[0]),Engine.N(p[1]));flow.Controls.Add(points);var construction=new CheckBox{Text="Вспомогательная геометрия",Width=280,Checked=selected.Construction};construction.CheckedChanged+=(s,e)=>{selected.Construction=construction.Checked;canvas.Invalidate();};flow.Controls.Add(construction);AddAction(flow,"Применить размеры / координаты",()=>{try{points.EndEdit();var values=editor==null?new Dictionary<string,string>():editor.Values();foreach(var p in values){double n=CADExpression.Evaluate(p.Value,canvas.Parameters);if(n<=0)throw new Exception("Размер должен быть положительным.");if(p.Key=="Radius")selected.Radius=p.Value;if(p.Key=="Width")selected.Width=p.Value;if(p.Key=="Height")selected.Height=p.Value;if(p.Key=="Count")selected.Count=p.Value;}for(int i=0;i<points.Rows.Count;i++)selected.Points[i]=new[]{CADExpression.Evaluate(Convert.ToString(points.Rows[i].Cells[0].Value),canvas.Parameters),CADExpression.Evaluate(Convert.ToString(points.Rows[i].Cells[1].Value),canvas.Parameters)};canvas.Invalidate();}catch(Exception ex){ShowError(ex);}});AddAction(flow,"Удалить выбранную геометрию",canvas.DeleteSelection);}
   flow.Controls.Add(Label("СВЯЗИ И РАЗМЕРЫ\nДля двух объектов: инструмент «Выбор», затем Ctrl+щелчки.",62));var kindBox=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};var kinds=new[]{"horizontal","vertical","coincident","parallel","perpendicular","equal","tangent","concentric","fixed","length","radius","distance","angle"};kindBox.Items.AddRange(kinds.Select(CADTools.ConstraintName).ToArray());kindBox.SelectedIndex=0;flow.Controls.Add(kindBox);var value=new TextBox{Width=280,Text="10"};flow.Controls.Add(value);AddAction(flow,"Добавить связь / размер",()=>AddConstraint(kinds[kindBox.SelectedIndex],value.Text));constraints.Items.Clear();foreach(var c in canvas.Sketch.Constraints)constraints.Items.Add(c);constraints.Width=280;constraints.Height=130;flow.Controls.Add(constraints);AddAction(flow,"Удалить выбранную связь",()=>{var c=constraints.SelectedItem as CADConstraint;if(c!=null){canvas.Sketch.Constraints.Remove(c);FillSketchInspector();}});AddAction(flow,"Решить связи",SolveSketch);AddAction(flow,"✓ Завершить эскиз",FinishSketch);}
  static double[] ReadPoint(string text){var values=text.Split(';');if(values.Length!=3)throw new Exception("Координаты: X; Y; Z.");return values.Select(s=>CADExpression.Evaluate(s,null)).ToArray();}
  void AddConstraint(string kind,string value){try{var ids=canvas.Selected.ToList();int required=new[]{"horizontal","vertical","fixed","length","radius"}.Contains(kind)?1:2;if(ids.Count!=required)throw new Exception("Выберите "+required+" объект(а) инструментом «Выбор».");var a=canvas.Sketch.Entities.First(e=>e.Id==ids[0]);var b=ids.Count>1?canvas.Sketch.Entities.First(e=>e.Id==ids[1]):null;bool lineA=a.Kind=="line"||a.Kind=="polyline",lineB=b!=null&&(b.Kind=="line"||b.Kind=="polyline");if(new[]{"horizontal","vertical","length"}.Contains(kind)&&!lineA)throw new Exception("Эта связь применяется к линии.");if(new[]{"parallel","perpendicular","angle"}.Contains(kind)&&(!lineA||!lineB))throw new Exception("Выберите две линии.");if(kind=="radius"&&a.Kind!="circle")throw new Exception("Выберите окружность.");if(kind=="concentric"&&(a.Kind!="circle"||b.Kind!="circle"))throw new Exception("Выберите две окружности.");if(kind=="equal"&&!(lineA&&lineB||a.Kind=="circle"&&b.Kind=="circle"))throw new Exception("Равенство: две линии или две окружности.");if(kind=="tangent"&&!(a.Kind=="circle"&&(lineB||b.Kind=="circle")||b.Kind=="circle"&&lineA))throw new Exception("Касание: линия и окружность либо две окружности.");var c=new CADConstraint{Kind=kind,A=a.Id,B=b==null?null:b.Id,PointA=canvas.PointIndex(a.Id),PointB=b==null?0:canvas.PointIndex(b.Id),Value=value};if(kind=="fixed"){c.Points=a.Points.Select(p=>p.ToArray()).ToList();if(a.Kind=="circle")c.Value=a.Radius;}canvas.Sketch.Constraints.Add(c);FillSketchInspector();}catch(Exception ex){ShowError(ex);}}
  async void SolveSketch(){if(editingSketch==null||busy)return;busy=true;try{var result=await Task.Factory.StartNew(()=>kernel.Run(new CADDocument(),"solve_sketch",null,null,null,new Dictionary<string,object>{{"Sketch",canvas.Sketch},{"Parameters",Document.Parameters}}));canvas.Sketch=result.Sketch;editingSketch.Sketch=result.Sketch;canvas.Invalidate();FillSketchInspector();double freedom=result.ConstraintStatus["DegreesOfFreedom"];message.Text=freedom==0?"Эскиз полностью определён":"Осталось степеней свободы: "+freedom; }catch(Exception ex){ShowError(ex);}finally{busy=false;}}
  static void Coincidence(CADSketch sketch){var lines=sketch.Entities.Where(e=>e.Kind=="line"&&!e.Construction).ToList();for(int i=0;i<lines.Count;i++)for(int j=i+1;j<lines.Count;j++)for(int a=0;a<lines[i].Points.Count;a++)for(int b=0;b<lines[j].Points.Count;b++){var x=lines[i].Points[a];var y=lines[j].Points[b];if(Math.Abs(x[0]-y[0])+Math.Abs(x[1]-y[1])<1e-8&&!sketch.Constraints.Any(c=>c.Kind=="coincident"&&c.A==lines[i].Id&&c.B==lines[j].Id&&c.PointA==a&&c.PointB==b))sketch.Constraints.Add(new CADConstraint{Kind="coincident",A=lines[i].Id,B=lines[j].Id,PointA=a,PointB=b});}}
  async void FinishSketch(){if(editingSketch==null||busy)return;canvas.FinishChain();var draft=editingSketch;draft.Sketch=canvas.Sketch;Coincidence(draft.Sketch);busy=true;try{var result=await Task.Factory.StartNew(()=>kernel.Run(new CADDocument(),"solve_sketch",null,null,null,new Dictionary<string,object>{{"Sketch",draft.Sketch},{"Parameters",Document.Parameters}}));draft.Sketch=result.Sketch;busy=false;var next=Document.Clone();int i=next.Features.FindIndex(f=>f.Id==draft.Id);if(i>=0)next.Features[i]=draft;else next.Features.Insert(Math.Min(marker,next.Features.Count),draft);editingSketch=null;selectedFeature=draft.Id;canvas.Visible=false;host.Visible=true;ribbon.Visible=true;sketchTools.Visible=false;if(!await BuildCandidate(next,true,true)){editingSketch=draft;canvas.Sketch=draft.Sketch;canvas.Visible=true;host.Visible=false;ribbon.Visible=false;sketchTools.Visible=true;FillSketchInspector();}}catch(Exception ex){busy=false;ShowError(ex);}}
  void CancelSketch(){if(busy)return;editingSketch=null;canvas.Visible=false;host.Visible=true;ribbon.Visible=true;sketchTools.Visible=false;FillInspector();UpdateTitle();UpdateStartCard();}
  Wpf.Point Project(double[] p){var d=new Point3D(p[0],p[1],p[2])-Scene.Camera.Target;double scale=Scene.Root.ActualWidth/Math.Max(.01,Scene.Camera.Width);return new Wpf.Point(Scene.Root.ActualWidth/2+Vector3D.DotProduct(d,Scene.Camera.Right)*scale,Scene.Root.ActualHeight/2-Vector3D.DotProduct(d,Scene.Camera.Up)*scale);}
  void RefreshAdorners(){if(disposed||gizmoDragging)return;adorners.Children.Clear();faceVisual.Content=null;if(!Scene.Ready||Body==null)return;var body=Body;var writer=new MeshWriter();if(body.Display!=null&&pickedFaces.Count>0)for(int i=0;i<body.TriangleFaces.Length;i++)if(pickedFaces.Contains(body.TriangleFaces[i])){int a=i*3;writer.Triangle(body.Display.Points[a],body.Display.Points[a+1],body.Display.Points[a+2],body.Display.Normals[a],body.Display.Normals[a+1],body.Display.Normals[a+2]);}if(writer.I.Count>0){var mat=new DiffuseMaterial(new Media.SolidColorBrush(Media.Color.FromArgb(185,255,171,51)));faceVisual.Content=new GeometryModel3D{Geometry=writer.Finish().Geometry(),Material=mat,BackMaterial=mat};}
   foreach(var edge in body.Edges.Where(e=>pickedEdges.Contains(e.Id))){var poly=new Shapes.Polyline{Stroke=Media.Brushes.Orange,StrokeThickness=3.5,IsHitTestVisible=false};foreach(var p in edge.Points)poly.Points.Add(Project(p));adorners.Children.Add(poly);}
   var centre=Project(body.Center);for(int axis=0;axis<3;axis++){int selectedAxis=axis;var vector=axis==0?new Vector3D(1,0,0):axis==1?new Vector3D(0,1,0):new Vector3D(0,0,1);double dx=Vector3D.DotProduct(vector,Scene.Camera.Right),dy=-Vector3D.DotProduct(vector,Scene.Camera.Up),len=Math.Sqrt(dx*dx+dy*dy);if(len<.12)continue;var endpoint=new Wpf.Point(centre.X+dx/len*68,centre.Y+dy/len*68);var brush=axis==0?Media.Brushes.IndianRed:axis==1?Media.Brushes.SeaGreen:Media.Brushes.SteelBlue;adorners.Children.Add(new Shapes.Line{X1=centre.X,Y1=centre.Y,X2=endpoint.X,Y2=endpoint.Y,Stroke=brush,StrokeThickness=2,IsHitTestVisible=false});var thumb=new System.Windows.Controls.Primitives.Thumb{Width=23,Height=23,Background=brush,ToolTip="Перемещение по "+"XYZ"[axis]};var border=new Wpf.FrameworkElementFactory(typeof(WControls.Border));border.SetValue(WControls.Border.BackgroundProperty,brush);border.SetValue(WControls.Border.CornerRadiusProperty,new Wpf.CornerRadius(5));var text=new Wpf.FrameworkElementFactory(typeof(WControls.TextBlock));text.SetValue(WControls.TextBlock.TextProperty,"XYZ"[axis].ToString());text.SetValue(WControls.TextBlock.ForegroundProperty,Media.Brushes.White);text.SetValue(WControls.TextBlock.HorizontalAlignmentProperty,Wpf.HorizontalAlignment.Center);text.SetValue(WControls.TextBlock.VerticalAlignmentProperty,Wpf.VerticalAlignment.Center);border.AppendChild(text);thumb.Template=new WControls.ControlTemplate(typeof(System.Windows.Controls.Primitives.Thumb)){VisualTree=border};WControls.Canvas.SetLeft(thumb,endpoint.X-11);WControls.Canvas.SetTop(thumb,endpoint.Y-11);thumb.DragStarted+=(s,e)=>{gizmoDragging=true;gizmoAxis=selectedAxis;Scene.MoveAxis=selectedAxis;gizmoStart=WInput.Mouse.GetPosition(Scene.Root);gizmoDelta=new Vector3D();};thumb.DragDelta+=(s,e)=>{var point=WInput.Mouse.GetPosition(Scene.Root);var delta=Scene.DragDelta(gizmoStart,point);gizmoDelta=new Vector3D(AppSettings.Snap(delta.X),AppSettings.Snap(delta.Y),AppSettings.Snap(delta.Z));Scene.SetOffset(selectedBody,gizmoDelta);};thumb.DragCompleted+=(s,e)=>{gizmoDragging=false;if(e.Canceled)Scene.ResetPlacements();else if(gizmoDelta.LengthSquared>1e-10)CommitMove(selectedBody,gizmoDelta);RefreshAdorners();};adorners.Children.Add(thumb);}
   var views=new WControls.StackPanel{Orientation=WControls.Orientation.Horizontal};foreach(var title in new[]{"Верх","Фронт","Право","ISO"}){string value=title;var button=new WControls.Button{Content=title,Padding=new Wpf.Thickness(7),Margin=new Wpf.Thickness(2)};button.Click+=(s,e)=>{Scene.Camera.Preset(value=="Верх"?"Сверху":value=="Фронт"?"Спереди":value=="Право"?"Справа":"Изометрия");Scene.Fit();RefreshAdorners();};views.Children.Add(button);}WControls.Canvas.SetLeft(views,Math.Max(10,Scene.Root.ActualWidth-270));WControls.Canvas.SetTop(views,12);adorners.Children.Add(views);
  }
  static Dictionary<string,string> AskValues(IWin32Window owner,string title,Dictionary<string,string> values){using(var form=new Form{Text=title,Font=new Font("Segoe UI",10),Size=new Size(450,Math.Min(700,145+values.Count*40)),StartPosition=FormStartPosition.CenterParent}){var editor=new CADValueEditor(values);form.Controls.Add(editor);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=55,Padding=new Padding(8)};bar.Controls.Add(new Button{Text="Применить",Width=120,Height=32,DialogResult=DialogResult.OK});bar.Controls.Add(new Button{Text="Отмена",Width=100,Height=32,DialogResult=DialogResult.Cancel});form.Controls.Add(bar);return form.ShowDialog(owner)==DialogResult.OK?editor.Values():null;}}
  void Material(){if(Body==null)return;CADMaterial old;if(!Document.Materials.TryGetValue(selectedBody,out old))old=new CADMaterial();using(var form=new Form{Text="Материал и цвет",Font=Font,Size=new Size(440,320),StartPosition=FormStartPosition.CenterParent}){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(15)};var choose=new ComboBox{Width=370,DropDownStyle=ComboBoxStyle.DropDownList};choose.Items.AddRange(new[]{"Алюминий · 2700","Сталь · 7850","PLA · 1240","PETG · 1270","ABS · 1040","Вручную"});choose.SelectedIndex=5;var density=new TextBox{Width=370,Text=Engine.N(old.Density)};var color=Color.FromArgb(old.Color);choose.SelectedIndexChanged+=(s,e)=>{if(choose.SelectedIndex<5)density.Text=new[]{"2700","7850","1240","1270","1040"}[choose.SelectedIndex];};panel.Controls.Add(choose);panel.Controls.Add(new Label{Text="Плотность, кг/м³",Width=370});panel.Controls.Add(density);var colorButton=new Button{Text="Цвет поверхности",Width=180,Height=34,BackColor=color};colorButton.Click+=(s,e)=>{using(var picker=new ColorDialog{Color=color})if(picker.ShowDialog(form)==DialogResult.OK){color=picker.Color;colorButton.BackColor=color;}};panel.Controls.Add(colorButton);var ok=new Button{Text="Применить",Width=180,Height=34};ok.Click+=(s,e)=>{try{double value=CADExpression.Evaluate(density.Text,null);if(value<100||value>30000)throw new Exception("Плотность 100–30000 кг/м³.");undo.Push(Document.Serialize());redo.Clear();Document.Materials[selectedBody]=new CADMaterial{Name=choose.SelectedIndex==5?"Пользовательский":choose.Text.Split('·')[0].Trim(),Density=value,Color=color.ToArgb()};Render(Document,State,false);UpdateTitle();form.DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(form,ex.Message);}};panel.Controls.Add(ok);form.Controls.Add(panel);form.ShowDialog(this);}}
  void Measure(){measuring=true;measuredFirst=null;message.Text="Измерение: выберите две точки на поверхностях тел.";}
  void Section(){var values=AskValues(this,"Сечение просмотра",new Dictionary<string,string>{{"Plane","XY"},{"Distance","0"},{"Through","true"}});if(values==null)return;try{Scene.Axis=values["Through"]=="true"?(values["Plane"]=="XY"?2:values["Plane"]=="XZ"?1:0):-1;Scene.Coordinate=CADExpression.Evaluate(values["Distance"],State.Parameters);Scene.Positive=true;Scene.UpdatePose(0);}catch(Exception ex){ShowError(ex);}}
  void Polygon(){if(Body==null)return;var mesh=MeshDocument.FromScene(Body.Display,CADTools.BodyName(Document,selectedBody));new PolygonForm(mesh,null).ShowWorkspace(this);}
  void WaveLibrary(){if(busy||editingSketch!=null)return;WorkspaceHost.OpenWave(this,kernel,async feature=>{var next=Document.Clone();WaveParameters.ApplyMaterials(next,feature);next.Features.Insert(Math.Min(marker,next.Features.Count),feature);return await BuildCandidate(next,true,true);});}
  void GearLibrary(){if(busy||editingSketch!=null)return;using(var library=new CADGearLibrary(kernel,async feature=>{var next=Document.Clone();next.Features.Insert(Math.Min(marker,next.Features.Count),feature);return await BuildCandidate(next,true,true);},Document.Parameters))library.ShowDialog(this);}
  void Search(){using(var form=new Form{Text="Найти команду",Size=new Size(500,550),Font=Font,StartPosition=FormStartPosition.CenterParent}){var search=new TextBox{Dock=DockStyle.Top};var list=new ListBox{Dock=DockStyle.Fill};string[] kinds={"sketch","extrude","revolve","loft","sweep","box","cylinder","sphere","hole","presspull","fillet","chamfer","shell","draft","combine","split","move","scale","mirror","linear_pattern","circular_pattern","wave","gear"};Action fill=()=>{list.Items.Clear();foreach(var k in kinds.Where(k=>CADTools.Name(k).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0))list.Items.Add(k);if(list.Items.Count>0)list.SelectedIndex=0;};list.Format+=(s,e)=>e.Value=CADTools.Name(Convert.ToString(e.ListItem));search.TextChanged+=(s,e)=>fill();Action run=()=>{string k=list.SelectedItem as string;if(k==null)return;form.Close();if(k=="sketch")BeginSketch(null);else if(k=="wave")WaveLibrary();else if(k=="gear")GearLibrary();else Operation(k);};list.DoubleClick+=(s,e)=>run();search.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){run();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.Down)list.Focus();};form.Controls.Add(list);form.Controls.Add(search);fill();form.ShowDialog(this);}}
  void Hotkey(KeyEventArgs e){if(e.Control&&e.KeyCode==Keys.S){Save(e.Shift);e.Handled=e.SuppressKeyPress=true;return;}if(e.Control&&e.KeyCode==Keys.Z){Undo();e.Handled=e.SuppressKeyPress=true;return;}if(e.Control&&e.KeyCode==Keys.Y){Redo();e.Handled=e.SuppressKeyPress=true;return;}if(ActiveControl is TextBox||ActiveControl is DataGridView||e.Control||e.Alt)return;if(editingSketch!=null){if(e.KeyCode==Keys.L)canvas.SetTool("line");else if(e.KeyCode==Keys.R)canvas.SetTool("rectangle");else if(e.KeyCode==Keys.C)canvas.SetTool("circle");else if(e.KeyCode==Keys.D)FillSketchInspector();else return;e.Handled=true;return;}switch(e.KeyCode){case Keys.E:Operation("extrude");break;case Keys.Q:Operation("presspull");break;case Keys.F:Operation("fillet");break;case Keys.M:Operation("move");break;case Keys.S:Search();break;default:return;}e.Handled=true;}
 }
}

